<script setup lang="ts">
import { ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { state,createDraft,changed,flush,run } from '../store';
const route=useRoute(),router=useRouter(),draft=state.drafts.find(d=>d.key===route.params.key);
const local=(value:string)=>{const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const timestamp=ref(local(draft?.timestamp||new Date().toISOString())),group=ref(draft?.group_id||state.cache?.suggestedGroupId||''),busy=ref(false);
async function save(){busy.value=true;await run(async()=>{if(!group.value)throw Error('اختر مجموعة.');if(draft){draft.group_id=Number(group.value);draft.timestamp=new Date(timestamp.value).toISOString();changed(draft);await flush();await router.push('/session/'+draft.key)}else{const created=await createDraft(Number(group.value),new Date(timestamp.value).toISOString());await router.replace('/session/'+created.key)}});busy.value=false}
</script>
<template><section class="narrow"><RouterLink to="/" class="back">→ الحصص</RouterLink><h1>{{draft?'تعديل الحصة':'إنشاء حصة'}}</h1><form v-if="state.cache" class="card form" @submit.prevent="save"><label>التاريخ والوقت<input v-model="timestamp" type="datetime-local" required></label><label>المجموعة<select v-model="group" required><option value="" disabled>اختر مجموعة</option><option v-for="g in state.cache.groups" :key="g.id" :value="g.id">{{g.name}}{{g.suggested?' · آخر مجموعة درّستها':''}}</option></select></label><p v-if="draft" class="muted">تغيير المجموعة يحافظ على طلاب الحصة والعمل المسجل.</p><button class="primary" :disabled="busy">{{draft?'حفظ التعديل':'إنشاء الحصة'}}</button></form><p v-else class="notice">جهّز بيانات المدرسة من الرئيسية أولًا.</p></section></template>
